  function detectInitialLang() {
    const params = new URLSearchParams(window.location.search);
    const qLang = params.get('lang');
    if (qLang === 'et' || qLang === 'en') return qLang;
    const saved = localStorage.getItem('unelm_ag1_lang');
    if (saved === 'et' || saved === 'en') return saved;
    return 'en';
  }

  function getPricing() {
    const tierGroup = state.mode === 'pod' ? CATALOG.pod[state.duration] : CATALOG.stay;
    const item = tierGroup[state.option] || tierGroup.M;
    const basePrice = state.purchaseType === 'founding' ? item.founding : item.standard;
    const anchorPrice = state.purchaseType === 'founding' ? item.anchor : item.standard;

    let bumpsTotal = 0;
    const selectedBumps = [];
    Object.keys(state.bumps).forEach(k => {
      if (state.bumps[k] && BUMPS[k]) {
        bumpsTotal += BUMPS[k].price;
        selectedBumps.push({
          id: k,
          title: BUMPS[k][state.lang],
          price: BUMPS[k].price
        });
      }
    });

    const totalPrice = basePrice + bumpsTotal;
    const totalAnchor = anchorPrice + bumpsTotal;

    return {
      item,
      basePrice,
      anchorPrice,
      foundingPrice: item.founding,
      standardPrice: item.standard,
      foundingAnchor: item.anchor,
      bumpsTotal,
      totalPrice,
      totalAnchor,
      selectedBumps,
      seasonInfo: item.seasonInfo[state.lang]
    };
  }

  function getOptionTitle() {
    const t = I18N[state.lang];
    if (state.mode === 'pod') {
      if (state.option === 'M') return t.optMTitlePod;
      if (state.option === 'L') return t.optLTitlePod;
      return t.optSTitlePod;
    } else {
      if (state.option === 'M') return t.optMTitleStay;
      if (state.option === 'L') return t.optLTitleStay;
      return t.optSTitleStay;
    }
  }

