          ${state.purchaseType === 'founding' ? `<div style="font-size:12px;color:#757575;text-decoration:line-through;">€${p.totalAnchor.toFixed(2)}</div>` : ''}
        </div>
      </div>
    `;
    document.querySelectorAll('.ag-live-summary-target').forEach(el => {
      el.innerHTML = summaryHtml;
    });
  }

  function setSlide(index) {
    const slides = document.querySelectorAll('.ag-slide');
    const dots = document.querySelectorAll('.ag-dot');
    const thumbs = document.querySelectorAll('.ag-thumb-btn');
    if (!slides.length) return;
    state.slideIndex = (index + slides.length) % slides.length;
    slides.forEach((s, i) => s.classList.toggle('active', i === state.slideIndex));
    dots.forEach((d, i) => d.classList.toggle('active', i === state.slideIndex));
    thumbs.forEach((t, i) => t.classList.toggle('active', i === state.slideIndex));
  }

  function openModal() {
    const modal = document.getElementById('ag-preorder-modal');
    if (modal) {
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      render();
    }
  }

  function closeModal() {
    const modal = document.getElementById('ag-preorder-modal');
    if (modal) {
      modal.classList.remove('open');
      document.body.style.overflow = '';
    }
  }

  async function handlePreorderSubmit(e) {
    e.preventDefault();
    const form = e.currentTarget;
    const submitBtn = form.querySelector('button[type="submit"]');
    const statusBox = form.parentElement.querySelector('.ag-success-box');

    const fd = new FormData(form);
    const customer_name = (fd.get('name') || '').toString().trim();
    const customer_email = (fd.get('email') || '').toString().trim();
    const customer_phone = (fd.get('phone') || '').toString().trim();
    const customer_country = (fd.get('country') || '').toString().trim();
    const preferred_dates = (fd.get('dates') || '').toString().trim();
    const guests = (fd.get('guests') || '2').toString().trim();
    const notes = (fd.get('notes') || '').toString().trim();

    if (!customer_name || !customer_email) {
      alert(state.lang === 'et' ? 'Palun sisesta oma nimi ja e-posti aadress.' : 'Please enter your name and email address.');
      return;
    }

    const p = getPricing();
    const refId = `UNELM-${Date.now().toString(36).toUpperCase().slice(-6)}`;
    const payload = {
      reference_id: refId,
      lang: state.lang,
      mode: state.mode,
      duration_mode: state.duration,
      package_id: state.option,
      package_title: getOptionTitle(),
      purchase_type: state.purchaseType,
      purchase_type_label: state.purchaseType === 'founding'
        ? 'Founding Member Preorder & Save (incl. €237 Free Bundle)'
        : 'One-Time Standard Booking',
      base_price: p.basePrice,
      anchor_price: p.totalAnchor,
      addons: p.selectedBumps,
      addons_total: p.bumpsTotal,
      total_price: p.totalPrice,
      customer_name,
      customer_email,
      customer_phone,
      customer_country,
      preferred_dates,
      guests,
      notes,
      source_url: window.location.href
    };

    const origBtnHtml = submitBtn ? submitBtn.innerHTML : '';
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.innerHTML = state.lang === 'et' ? 'Saadan eeltellimust...' : 'Submitting Preorder...';
    }

    // Save locally as backup
    try {
      const saved = JSON.parse(localStorage.getItem('unelm_preorders') || '[]');
      saved.push({ ...payload, created_at: new Date().toISOString() });
      localStorage.setItem('unelm_preorders', JSON.stringify(saved));
    } catch (_) {}

    let apiOk = false;
    try {
      const resp = await fetch('/api/preorder', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const resData = await resp.json().catch(() => ({}));
      if (resp.ok && resData.ok) {
        apiOk = true;
      }
    } catch (_) {}

    // Client-side direct fallback to FormSubmit for reneealuste@gmail.com if serverless route wasn't hit
    if (!apiOk) {
      try {
        await fetch('https://formsubmit.co/ajax/78c3a12c74aa756d1d5e36e3c5f0168b', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
          body: JSON.stringify({
            _subject: `[UNELM EELTELLIMUS ${refId}] ${payload.package_title} — €${payload.total_price} (${customer_name})`,
            _template: 'table',
            _captcha: 'false',
            _replyto: customer_email,
            Tellimuse_kood: refId,
            Valitud_pakett: payload.package_title,
            Ostutüüp: payload.purchase_type_label,
            Lisad: payload.addons.map(a => `${a.title} (+€${a.price})`).join(', ') || '—',
            Kogusumma: `€${payload.total_price}`,
            Nimi: customer_name,
            Epost: customer_email,
            Telefon: customer_phone,
            Riik: customer_country,
            Soovitud_kuupäevad: preferred_dates,
            Märkused: notes
          })
        });
      } catch (_) {}
    }

    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.innerHTML = origBtnHtml;
    }

    form.style.display = 'none';
    if (statusBox) {
      const mailtoSubject = encodeURIComponent(`[Unelm Preorder ${refId}] ${payload.package_title}`);
      const mailtoBody = encodeURIComponent(
        `Hello Renee,\n\nI just completed my Unelm Founding Preorder (${refId}):\n` +
        `• Package: ${payload.package_title}\n` +
        `• Purchase Type: ${payload.purchase_type_label}\n` +
        `• Add-ons: ${payload.addons.map(a => a.title).join(', ') || 'None'}\n` +
        `• Total: €${payload.total_price.toFixed(2)}\n` +
        `• Name: ${customer_name}\n` +
        `• Email: ${customer_email}\n` +
        `• Phone: ${customer_phone}\n` +
        `• Preferred Dates/Season: ${preferred_dates}\n` +
        `• Notes: ${notes}\n`
      );
      statusBox.classList.add('visible');
      statusBox.innerHTML = state.lang === 'et'
        ? `
          <div style="font-size:36px;margin-bottom:6px;">🌿</div>
          <h3 style="margin:0 0 8px;color:#0b3b2e;font-size:22px;">Eeltellimus kinnitatud! Kood: <code>${refId}</code></h3>
          <p style="margin:0 0 12px;font-size:14.5px;color:#223029;">
            Sinu asutajaliikme eeltellimus (<b>${payload.package_title}</b> — <b>€${payload.total_price.toFixed(2)}</b> koos 237 € boonuspaketiga) on saadetud aadressile <b>reneealuste@gmail.com</b>.
          </p>
          <p style="margin:0 0 16px;font-size:13px;color:#49544f;">
            🔒 Kehtib 100% Raha Tagasi Garantii kuni 1. maini 2027 (ja 30-päevane rahulolugarantii). Renee võtab sinuga 24h jooksul ühendust aadressil <b>${customer_email}</b>.
          </p>
          <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">
            <a href="mailto:reneealuste@gmail.com?subject=${mailtoSubject}&body=${mailtoBody}" class="ag-btn-bright" style="height:42px;font-size:14px;max-width:260px;">Saada koopia ka oma e-postist →</a>
          </div>
        `
        : `
          <div style="font-size:36px;margin-bottom:6px;">🌿</div>
          <h3 style="margin:0 0 8px;color:#0b3b2e;font-size:22px;">Preorder Reserved! Code: <code>${refId}</code></h3>
          <p style="margin:0 0 12px;font-size:14.5px;color:#223029;">
            Your Founding Preorder (<b>${payload.package_title}</b> — <b>€${payload.total_price.toFixed(2)}</b> incl. €237 free welcome bundle) has been routed directly to <b>reneealuste@gmail.com</b>.
          </p>
          <p style="margin:0 0 16px;font-size:13px;color:#49544f;">
            🔒 Protected by our 100% Money-Back Guarantee up to May 1, 2027 (and 30-day stay guarantee). Renee will confirm your pod & dates within 24 hours at <b>${customer_email}</b>.
          </p>
          <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">
            <a href="mailto:reneealuste@gmail.com?subject=${mailtoSubject}&body=${mailtoBody}" class="ag-btn-bright" style="height:42px;font-size:14px;max-width:260px;">Send Backup Copy via Email App →</a>
          </div>
        `;
    }
  }

  document.addEventListener('DOMContentLoaded', () => {
    state.lang = detectInitialLang();

    // Language switchers
    document.querySelectorAll('[data-set-lang]').forEach(btn => {
      btn.addEventListener('click', () => {
        state.lang = btn.getAttribute('data-set-lang');
        localStorage.setItem('unelm_ag1_lang', state.lang);
        render();
      });
    });

    // Mode tabs
    document.querySelectorAll('[data-mode-tab]').forEach(btn => {
      btn.addEventListener('click', () => {
        state.mode = btn.getAttribute('data-mode-tab');
        render();
      });
    });

    // Duration buttons
    document.querySelectorAll('[data-dur-btn]').forEach(btn => {
      btn.addEventListener('click', () => {
        state.duration = btn.getAttribute('data-dur-btn');
        render();
      });
    });

    // Option radio cards (M, L, S)
    document.querySelectorAll('[data-opt-card]').forEach(card => {
      card.addEventListener('click', () => {
        state.option = card.getAttribute('data-opt-card');
        render();
      });
    });

    // Purchase type cards (founding vs standard)
    document.querySelectorAll('[data-purchase-card]').forEach(card => {
      card.addEventListener('click', () => {
        state.purchaseType = card.getAttribute('data-purchase-card');
        render();
      });
    });

    // Order bump cards
    document.querySelectorAll('[data-bump-card]').forEach(card => {
      card.addEventListener('click', () => {
        const key = card.getAttribute('data-bump-card');
        state.bumps[key] = !state.bumps[key];
        render();
      });
    });

    // Carousel controls
    const prevBtn = document.getElementById('ag-slide-prev');
    const nextBtn = document.getElementById('ag-slide-next');
    if (prevBtn) prevBtn.addEventListener('click', () => setSlide(state.slideIndex - 1));
    if (nextBtn) nextBtn.addEventListener('click', () => setSlide(state.slideIndex + 1));
    document.querySelectorAll('.ag-dot').forEach((dot, idx) => {
      dot.addEventListener('click', () => setSlide(idx));
    });
    document.querySelectorAll('.ag-thumb-btn').forEach((thumb, idx) => {
      thumb.addEventListener('click', () => setSlide(idx));
    });

    // Masterplan tabs
    document.querySelectorAll('[data-plan-img]').forEach(btn => {
      btn.addEventListener('click', () => {
        const src = btn.getAttribute('data-plan-img');
        const img = document.getElementById('ag-masterplan-img');
        if (img && src) img.src = src;
        document.querySelectorAll('[data-plan-img]').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
      });
    });

    // Modal triggers
    document.querySelectorAll('[data-open-preorder]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        openModal();
      });
    });

    document.querySelectorAll('[data-close-preorder]').forEach(btn => {
      btn.addEventListener('click', closeModal);
    });

    const backdrop = document.getElementById('ag-preorder-modal');
    if (backdrop) {
      backdrop.addEventListener('click', (e) => {
        if (e.target === backdrop) closeModal();
      });
    }

    // Drawer menu
    const drawer = document.getElementById('ag-drawer');
    const menuBtn = document.getElementById('ag-menu-btn');
    const drawerClose = document.getElementById('ag-drawer-close');
    if (menuBtn && drawer) {
      menuBtn.addEventListener('click', () => drawer.classList.add('open'));
    }
    if (drawerClose && drawer) {
      drawerClose.addEventListener('click', () => drawer.classList.remove('open'));
    }
    if (drawer) {
      drawer.querySelectorAll('a').forEach(a => {
        a.addEventListener('click', () => drawer.classList.remove('open'));
      });
    }

    // Preorder forms (both modal and inline)
    document.querySelectorAll('.ag-preorder-form').forEach(form => {
      form.addEventListener('submit', handlePreorderSubmit);
    });

    render();
  });
})();

