/* Learning path ("Õpiteekond") — shared by /app/ and /vision/.
   Progress lives only in this browser (localStorage "unelm-learn"). Badges are a prototype of the idea. */
(function () {
  const V = window.UNELM_VISION, C = window.UNELM_CONFIG;
  const KEY = "unelm-learn";
  const TXT = {
    en: { path: "Learning path", steps: "{a} / {b} steps done", total: "≈ {h} of hands-on work", video: "How-to video · coming soon", ws: "On-site workshop available – 2 h group, {p} per person", wsTag: "ASSUMPTION · example price", badges: "Your badges", badgeHint: "Tick every item on a step card to complete it and earn its badge.", why: "Why", h: "h", min: "min", locked: "not yet" },
    et: { path: "Õpiteekond", steps: "{a} / {b} sammu tehtud", total: "≈ {h} käed-külge tööd", video: "Õppevideo · tulekul", ws: "Kohapealne töötuba saadaval – 2 h grupp, {p} inimese kohta", wsTag: "EELDUS · näidishind", badges: "Sinu märgid", badgeHint: "Märgi sammukaardil kõik punktid, et samm lõpetada ja märk teenida.", why: "Miks", h: "h", min: "min", locked: "veel mitte" }
  };
  const load = () => { try { return JSON.parse(localStorage.getItem(KEY) || "{}"); } catch (e) { return {}; } };
  let S = load();
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(S)); } catch (e) {} };
  const L = (id) => V.lessons[id];
  const f = (s, o) => s.replace(/\{(\w+)\}/g, (_, k) => o[k]);
  const dur = (min, lang) => (min >= 60 ? (Math.round(min / 30) / 2).toString().replace(".", lang === "et" ? "," : ".") + " " + TXT[lang].h : min + " " + TXT[lang].min);
  function isDone(id) { const l = L(id); const s = S[id] || []; return l.list.en.every((_, i) => s.includes(i)); }
  function toggle(id, i) { const s = new Set(S[id] || []); s.has(i) ? s.delete(i) : s.add(i); S[id] = [...s]; save(); }
  function progress(concept) { const done = concept.lessons.filter(isDone).length; return { done, total: concept.lessons.length, pct: Math.round(done / concept.lessons.length * 100), minutes: concept.lessons.reduce((a, id) => a + L(id).min, 0) }; }
  function badges() {
    const out = Object.entries(V.badges).filter(([k]) => k !== "done").map(([k, b]) => ({ key: k, icon: b.icon, b, earned: Object.keys(V.lessons).some((id) => L(id).badge === k && isDone(id)) }));
    out.push({ key: "done", icon: V.badges.done.icon, b: V.badges.done, earned: V.concepts.some((c) => c.lessons.every(isDone)) });
    return out;
  }
  function badgesHTML(lang) {
    return `<div class="lbadges" aria-label="${TXT[lang].badges}">${badges().map((x) => `<span class="lbadge ${x.earned ? "on" : ""}" title="${x.earned ? "" : TXT[lang].locked}"><i>${x.icon}</i>${x.b[lang]}</span>`).join("")}</div>`;
  }
  function headerHTML(concept, lang) {
    const p = progress(concept);
    return `<div class="lhead"><div class="lhead-top"><b>${TXT[lang].path}</b><span>${f(TXT[lang].steps, { a: p.done, b: p.total })} · ${f(TXT[lang].total, { h: dur(p.minutes, lang) })}</span></div><div class="lbar"><i style="width:${p.pct}%"></i></div></div>`;
  }
  function cardsHTML(concept, lang, opts = {}) {
    const wsPrice = ((C.addons || []).find((a) => a.id === "ws_group") || { price: 29 }).price;
    const diffs = V.difficulty[lang];
    return headerHTML(concept, lang) + `<ol class="lcards">` + concept.lessons.map((id, n) => {
      const l = L(id), done = isDone(id), s = S[id] || [];
      return `<li class="lcard ${done ? "done" : ""}" data-lesson="${id}"><details ${opts.open === n ? "open" : ""}><summary><span class="lnum">${done ? "✓" : n + 1}</span><span class="ltitle"><b>${l.t[lang]}</b><small>⏱ ${dur(l.min, lang)} · <span class="ldiff d${l.diff}" aria-label="${diffs[l.diff]}">${"●".repeat(l.diff + 1)}${"○".repeat(2 - l.diff)}</span> ${diffs[l.diff]} · ${V.badges[l.badge].icon}</small></span></summary>
        <p class="lwhy">${l.why[lang]}</p>
        <ul class="lchk">${l.list[lang].map((it, i) => `<li><label><input type="checkbox" data-l="${id}" data-i="${i}" ${s.includes(i) ? "checked" : ""}><span>${it}</span></label></li>`).join("")}</ul>
        <div class="lvideo" aria-disabled="true"><span class="play">▶</span>${TXT[lang].video}</div>
        ${l.ws ? `<div class="lws">🎓 ${f(TXT[lang].ws, { p: "€" + wsPrice })} <span class="tag-example">${TXT[lang].wsTag}</span></div>` : ""}
      </details></li>`;
    }).join("") + `</ol><p class="lhint">${TXT[lang].badgeHint}</p>` + badgesHTML(lang);
  }
  function bind(container, onChange) {
    container.querySelectorAll('input[type="checkbox"][data-l]').forEach((cb) => cb.addEventListener("change", () => { toggle(cb.dataset.l, +cb.dataset.i); onChange && onChange(cb.dataset.l); }));
  }
  window.UnelmLearn = { isDone, toggle, progress, badges, badgesHTML, cardsHTML, headerHTML, bind, dur, TXT, reset: () => { S = {}; save(); } };
})();

