/* Landing page behaviour: prices from config, language toggle, scroll effects, front-end-only form. */
(function () {
  const C = window.UNELM_CONFIG, P = window.UnelmPricing, I = window.UNELM_I18N;
  let lang = "et"; // Estonian first (Sep 2026); English is the inline fallback in index.html
  const t = (k) => (I[lang] && I[lang][k]) || (I.en && I.en[k]) || k;

  /* ---------- Prices (all PLACEHOLDER, from assets/js/config.js) ---------- */
  function renderPrices() {
    const tierVals = {};
    C.tiers.forEach((tier) => {
      const r = P.tierFrom(tier);
      tierVals[tier.id] = r;
      document.querySelectorAll(`[data-price="tier:${tier.id}"]`).forEach((el) => (el.textContent = P.fmt(P.charm(r.amount))));
      document.querySelectorAll(`[data-per="tier:${tier.id}"]`).forEach((el) => (el.textContent = t("per." + r.stay)));
      document.querySelectorAll(`[data-night="tier:${tier.id}"]`).forEach((el) => (el.textContent = t("per.night").replace("{x}", P.fmt(P.charm(r.amount) / (C.stays.find((s) => s.id === r.stay).nights)))));
    });
    // 2027 launch prices (business-plan.md §4.2) – config.launch
    const L = C.launch || {};
    document.querySelectorAll('[data-price^="launch:"]').forEach((el) => {
      const k = el.dataset.price.slice(7), v = typeof L[k] === "object" ? L[k].amount : L[k];
      if (v != null) el.textContent = (k.startsWith("buildPkg") ? "≈ " : "") + P.fmt(v);
    });
    const min = L.simple ? L.simple.amount : 0;
    document.querySelectorAll('[data-price="launch-min"]').forEach((el) => { el.dataset.target = min; el.textContent = P.fmt(el.dataset.shown ? min : 0); });
    // stay lengths, reference 50 m² simple plot rent
    C.stays.forEach((s) => {
      const q = P.quote({ plot: 50, layout: "kitchen", service: "diy", stay: s.id, addons: [] });
      const amt = P.charm(q.rent);
      document.querySelectorAll(`[data-stay="${s.id}"]`).forEach((el) => (el.textContent = P.fmt(amt)));
      document.querySelectorAll(`[data-stay-night="${s.id}"]`).forEach((el) => (el.textContent = t("per.night").replace("{x}", P.fmt(amt / s.nights))));
    });
    document.querySelectorAll('[data-price="camper-night"]').forEach((el) => (el.textContent = P.fmt(C.camper.perNight)));
    document.querySelectorAll('[data-price="camper-season"]').forEach((el) => (el.textContent = P.fmt(C.camper.perSeason)));
    // v3: generic config prices, e.g. <b data-cfg="pods.tiers.1.perNight"> or data-cfg="ev.perKwh"
    document.querySelectorAll("[data-cfg]").forEach((el) => {
      const v = el.dataset.cfg.split(".").reduce((o, k) => (o == null ? o : o[k]), C);
      if (typeof v === "number") el.textContent = v < 10 && v % 1 ? (lang === "et" ? v.toFixed(2).replace(".", ",") + " €" : "€" + v.toFixed(2)) : P.fmt(v);
      else if (v && typeof v === "object" && v[lang]) el.textContent = v[lang];
      else if (v != null) el.textContent = v;
    });
    if (!C.pricesArePlaceholders) document.querySelectorAll(".tag-example").forEach((el) => el.remove());
  }

  /* ---------- Count-up for the price reveal ---------- */
  function countUp(el) {
    if (el.dataset.shown) return; el.dataset.shown = 1;
    const target = +el.dataset.target, t0 = performance.now(), dur = 1400;
    const step = (now) => { const k = Math.min(1, (now - t0) / dur); el.textContent = P.fmt(Math.round(target * (1 - Math.pow(1 - k, 3)))); if (k < 1) requestAnimationFrame(step); };
    requestAnimationFrame(step);
  }

  /* ---------- Language ---------- */
  const originals = new Map();
  function setLang(l) {
    lang = l; document.documentElement.lang = l;
    document.querySelectorAll("[data-i18n]").forEach((el) => {
      if (!originals.has(el)) originals.set(el, el.innerHTML);
      const k = el.dataset.i18n;
      el.innerHTML = l === "en" ? originals.get(el) : (I[l] && I[l][k]) || originals.get(el);
    });
    document.querySelectorAll(".lang button").forEach((b) => b.setAttribute("aria-pressed", b.dataset.lang === l));
    renderPrices();
    try { localStorage.setItem("unelm-lang", l); } catch (e) {}
  }
  document.querySelectorAll(".lang button").forEach((b) => b.addEventListener("click", () => setLang(b.dataset.lang)));

  /* ---------- Nav + reveal on scroll ---------- */
  const nav = document.getElementById("nav");
  const onScroll = () => nav.classList.toggle("solid", window.scrollY > 60);
  window.addEventListener("scroll", onScroll, { passive: true }); onScroll();
  const io = new IntersectionObserver((entries) => entries.forEach((e) => {
    if (!e.isIntersecting) return;
    e.target.classList.add("in");
    e.target.querySelectorAll("[data-target]").forEach(countUp);
    io.unobserve(e.target);
  }), { threshold: 0.15 });
  document.querySelectorAll(".rv").forEach((el) => io.observe(el));

  /* ---------- Pre-registration form: PROTOTYPE – saved only in this browser (localStorage), nothing is sent ---------- */
  const form = document.getElementById("reserve-form");
  const interestSel = document.getElementById("f-interest"), tierSel = document.getElementById("f-tier");
  function preselect(v) {
    if (!v || !interestSel) return;
    interestSel.value = v;
    if ((v === "stay" || v === "longstay" || v === "pod") && tierSel) tierSel.value = "none";
    if (v === "longstay") document.getElementById("f-stay").value = "month";
  }
  document.querySelectorAll("[data-interest]").forEach((a) => a.addEventListener("click", () => preselect(a.dataset.interest)));
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    if (!form.checkValidity()) { form.reportValidity(); return; }
    // TODO (go-live): send to a real backend / form service (or mailto fallback) + privacy policy (GDPR).
    try {
      const entry = Object.fromEntries(new FormData(form).entries());
      entry.lang = lang; entry.at = new Date().toISOString();
      const all = JSON.parse(localStorage.getItem("unelm-interest") || "[]"); all.push(entry);
      localStorage.setItem("unelm-interest", JSON.stringify(all));
    } catch (err) {}
    form.classList.add("done");
  });

  /* ---------- Airbnb placeholder: real URL goes to config.airbnbUrl (TODO) ---------- */
  document.querySelectorAll("[data-airbnb]").forEach((a) => {
    if (C.airbnbUrl) { a.href = C.airbnbUrl; a.target = "_blank"; a.rel = "noopener"; a.removeAttribute("data-interest"); }
  });
  if (C.airbnbUrl) document.querySelectorAll("[data-airbnb-note]").forEach((el) => el.remove());

  /* ---------- init ---------- */
  let saved = "et"; try { saved = localStorage.getItem("unelm-lang") || "et"; } catch (e) {}
  const q = new URLSearchParams(location.search).get("lang"); if (q) saved = q;
  setLang(saved === "en" ? "en" : "et");
  if (new URLSearchParams(location.search).has("static")) document.querySelectorAll(".rv").forEach((el) => { el.classList.add("in"); el.querySelectorAll("[data-target]").forEach(countUp); });
})();

