/* Shared pricing formula for landing page + app. All inputs come from window.UNELM_CONFIG (PLACEHOLDER prices). */
(function () {
  const C = window.UNELM_CONFIG;
  const by = (arr, id) => arr.find((x) => x.id === id);

  function quote(sel) {
    const plot = C.plots.find((p) => p.m2 === sel.plot) || C.plots[0];
    const stay = by(C.stays, sel.stay) || C.stays[0];
    const svc = by(C.services, sel.service) || C.services[0];
    const layout = by(C.layouts, sel.layout) || C.layouts[0];
    const m2 = plot.m2;

    const rent = Math.max(C.minimumRent, m2 * stay.rentPerM2 * svc.rentFactor);
    // ready-made items are rented: charge a share of their value depending on stay length
    const share = svc.id === "ready" ? Math.min(1, Math.max(C.readyMadeMinSeasonShare, stay.nights / 150)) : 1;
    const matF = svc.materialFactor * share;

    const areas = { beds: m2 * layout.beds, paths: m2 * layout.paths };
    areas.ground = Math.max(0, m2 - areas.beds - areas.paths);
    const mats = svc.id === "simple"
      ? { beds: by(C.materials.beds, "wood"), paths: by(C.materials.paths, "mown"), ground: by(C.materials.ground, "lawn") }
      : { beds: by(C.materials.beds, sel.beds), paths: by(C.materials.paths, sel.paths), ground: by(C.materials.ground, sel.ground) };

    let build = 0;
    const buildLines = [];
    for (const k of ["beds", "paths", "ground"]) {
      const m = mats[k]; if (!m) continue;
      const cost = areas[k] * (m.price * matF + (svc.labour ? m.labour : 0));
      build += cost; buildLines.push({ key: k, id: m.id, m2: areas[k], cost });
    }

    let addons = 0;
    const addonLines = [];
    for (const id of sel.addons || []) {
      const a = by(C.addons, id); if (!a) continue;
      // simple tier: add-ons bought at DIY price (material only)
      // kit add-ons (stream & waterfall): materials bought new per order → always full price;
      // build fee applies when we build it (ready-made or built-for-you)
      const f = a.kit || svc.id === "simple" ? 1 : matF;
      const lab = a.kit ? (svc.labour || svc.id === "ready") : svc.labour;
      const cost = a.price * f + (lab ? a.labour : 0);
      addons += cost; addonLines.push({ id, cost });
    }

    let fees = svc.fixedFee;
    if (svc.id === "diy" && (build > 0 || addons > 0)) fees += C.deliveryFee;

    const total = rent + build + addons + fees;
    return {
      m2, stay, service: svc, rent, build, buildLines, addons, addonLines, fees, total,
      perNight: total / stay.nights, areas
    };
  }

  function tierFrom(tier) {
    if (tier.override) return { amount: tier.override.amount, stay: tier.reference.stay };
    const q = quote(tier.reference);
    const amount = tier.excludeBuild ? q.rent : q.total;
    return { amount, stay: q.stay.id, perNight: amount / q.stay.nights, q };
  }

  // Marketing rounding: 287 -> 289, 1234 -> 1249 ("charm" pricing on placeholders)
  function charm(n) {
    if (n < 100) return Math.ceil(n);
    if (n < 1000) return Math.ceil((n + 1) / 10) * 10 - 1;
    return Math.ceil((n + 1) / 50) * 50 - 1;
  }
  const fmt = (n, cur = C.currency) => cur + Math.round(n).toLocaleString("en-US").replace(/,/g, "\u202f");

  window.UnelmPricing = { quote, tierFrom, charm, fmt };
})();

