/* Top-down 2D garden plan renderer (SVG, units = metres). Pure function: state -> SVG markup. */
(function () {
  const C = window.UNELM_CONFIG;
  const by = (a, id) => a.find((x) => x.id === id);

  function rng(seed) { let s = seed >>> 0 || 1; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }

  const GROUND = { lawn: "#9dbb7a", meadow: "#b8c27a", clover: "#8fb573", moss: "#6f8f5a" };
  const PATH = { gravel: "#ddd3bf", stone: "#c3bcaf", woodchip: "#a67f58", mown: "#b9d08e" };
  const BEDEDGE = { wood: "#b88a5a", corten: "#9c4a24", stone: "#9a968e", ground: "none" };
  const SOIL = "#6b4f3a";
  const LEAF = ["#4f6f45", "#5e7a55", "#6d8a5a", "#3f5a3f"];

  function defs(uid, st) {
    return `<defs>
      <pattern id="g${uid}" width="0.6" height="0.6" patternUnits="userSpaceOnUse"><rect width="0.6" height="0.6" fill="${GROUND[st.ground] || GROUND.lawn}"/><path d="M.1 .45l.05-.15M.4 .5l.05-.18" stroke="rgba(0,0,0,.08)" stroke-width=".04"/></pattern>
      <pattern id="gr${uid}" width="0.5" height="0.5" patternUnits="userSpaceOnUse"><rect width="0.5" height="0.5" fill="${PATH.gravel}"/><circle cx=".1" cy=".15" r=".03" fill="#bfb49c"/><circle cx=".35" cy=".38" r=".025" fill="#c9bea6"/></pattern>
      <pattern id="st${uid}" width="0.8" height="0.5" patternUnits="userSpaceOnUse"><rect width="0.8" height="0.5" fill="${PATH.stone}"/><path d="M0 0H.8M0 .25H.8M.4 0V.25M0 .25V.5M.8 .25V.5" stroke="#a79f92" stroke-width=".03"/></pattern>
      <pattern id="wc${uid}" width="0.4" height="0.4" patternUnits="userSpaceOnUse"><rect width="0.4" height="0.4" fill="${PATH.woodchip}"/><path d="M.05 .1l.12 .04M.22 .3l.1-.05" stroke="#8a6644" stroke-width=".04"/></pattern>
      <pattern id="mw${uid}" width="1" height="1" patternUnits="userSpaceOnUse"><rect width="1" height="1" fill="${PATH.mown}"/><rect width=".5" height="1" fill="#afc785"/></pattern>
      <pattern id="rk${uid}" width="0.3" height="0.3" patternUnits="userSpaceOnUse"><rect width="0.3" height="0.3" fill="${PATH.gravel}"/><path d="M0 .15H.3" stroke="#c8bda6" stroke-width=".04"/></pattern>
      <filter id="sh${uid}" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx=".08" dy=".12" stdDeviation=".1" flood-opacity=".3"/></filter>
    </defs>`;
  }
  const pathFill = (uid, id, raked) => raked && id === "gravel" ? `url(#rk${uid})` : ({ gravel: `url(#gr${uid})`, stone: `url(#st${uid})`, woodchip: `url(#wc${uid})`, mown: `url(#mw${uid})` }[id] || PATH.gravel);

  function plants(r, x, y, w, h, pal, density, flowerShare = 0.55) {
    let s = ""; const n = Math.max(2, Math.round(w * h * density));
    for (let i = 0; i < n; i++) {
      const px = x + 0.15 + r() * Math.max(0.01, w - 0.3), py = y + 0.15 + r() * Math.max(0.01, h - 0.3);
      if (r() < flowerShare) s += `<circle cx="${px.toFixed(2)}" cy="${py.toFixed(2)}" r="${(0.08 + r() * 0.1).toFixed(2)}" fill="${pal[Math.floor(r() * pal.length)]}"/>`;
      else s += `<circle cx="${px.toFixed(2)}" cy="${py.toFixed(2)}" r="${(0.14 + r() * 0.16).toFixed(2)}" fill="${LEAF[Math.floor(r() * LEAF.length)]}"/>`;
    }
    return s;
  }
  function bed(r, st, x, y, w, h, pal, dens = 7, fShare) {
    const edge = BEDEDGE[st.beds] || "none", rx = st.beds === "ground" ? Math.min(w, h) * 0.3 : 0.06;
    let s = `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${SOIL}" ${edge !== "none" ? `stroke="${edge}" stroke-width="0.12"` : ""}/>`;
    return s + plants(r, x, y, w, h, pal, dens, fShare);
  }
  function tree(x, y, rad, color) {
    return `<circle cx="${x + rad * 0.25}" cy="${y + rad * 0.3}" r="${rad}" fill="rgba(0,0,0,.14)"/><circle cx="${x}" cy="${y}" r="${rad}" fill="${color}"/><circle cx="${x - rad * 0.3}" cy="${y - rad * 0.3}" r="${rad * 0.45}" fill="rgba(255,255,255,.12)"/>`;
  }

  /* ---------------- layouts ---------------- */
  function layoutSvg(st, W, D, uid, pal, r) {
    const pf = pathFill(uid, st.paths), m = 0.35; // hedge margin
    const iw = W - 2 * m, id = D - 2 * m, gx = W / 2;
    let s = "";
    const occupied = [{ x: gx - 0.7, y: D * 0.55, w: 1.4, h: D * 0.45 }]; // keep the entry path free for add-ons
    switch (st.layout) {
      case "kitchen": {
        const pw = Math.min(1, W * 0.12), bw = 1.2, gap = 0.5;
        s += `<rect x="${m}" y="${m}" width="${iw}" height="${id}" fill="${pf}"/>`;
        const cols = [[m + 0.3, gx - pw / 2 - 0.3], [gx + pw / 2 + 0.3, W - m - 0.3]];
        for (const [x0, x1] of cols) {
          for (let y = m + 0.4; y + bw <= D - m - 0.4; y += bw + gap) s += bed(r, st, +x0.toFixed(2), +y.toFixed(2), +(x1 - x0).toFixed(2), bw, pal, 6, 0.35);
        }
        s += `<rect x="${gx - pw / 2}" y="${m}" width="${pw}" height="${D - m}" fill="${pf}" stroke="rgba(0,0,0,.08)" stroke-width=".04"/>`;
        break;
      }
      case "zen": {
        s += `<rect x="${m}" y="${m}" width="${iw}" height="${id}" fill="${pathFill(uid, st.paths, true)}"/>`;
        s += `<rect x="${m + 0.2}" y="${m + 0.2}" width="${iw - 0.4}" height="${Math.min(1.2, id * 0.12)}" rx=".1" fill="${SOIL}" stroke="${BEDEDGE[st.beds] === "none" ? "none" : BEDEDGE[st.beds]}" stroke-width=".1"/>` + plants(r, m + 0.2, m + 0.2, iw - 0.4, Math.min(1.2, id * 0.12), pal, 5, 0.3);
        const isl = [[0.3, 0.45, 0.22, 0.14], [0.7, 0.62, 0.18, 0.12], [0.45, 0.8, 0.12, 0.08]];
        for (const [fx, fy, rx, ry] of isl) s += `<ellipse cx="${W * fx}" cy="${D * fy}" rx="${W * rx}" ry="${D * ry}" fill="url(#g${uid})"/>`;
        const stones = [[0.34, 0.43, 0.45], [0.68, 0.6, 0.35], [0.74, 0.64, 0.22], [0.47, 0.8, 0.25]];
        for (const [fx, fy, rr] of stones) s += `<ellipse cx="${W * fx}" cy="${D * fy}" rx="${rr * 1.2}" ry="${rr}" fill="#8f8a82" filter="url(#sh${uid})"/>`;
        s += tree(W * 0.78, D * 0.3, Math.min(W, D) * 0.14, pal[pal.length - 1]);
        for (let i = 0; i < 6; i++) { const t = i / 5; s += `<rect x="${gx - 0.35 + Math.sin(t * 3) * W * 0.12}" y="${D - m - 0.5 - t * D * 0.4}" width=".7" height=".45" rx=".12" fill="#b3ab9d" stroke="#8f887b" stroke-width=".03"/>`; }
        s += `<rect x="${m + 0.4}" y="${D * 0.55}" width="${Math.min(2.4, iw * 0.35)}" height="${Math.min(1.8, id * 0.2)}" fill="#b98c5f" stroke="#8a6644" stroke-width=".05"/>`;
        break;
      }
      case "meadow": {
        s += plants(r, m, m, iw, id, pal.concat(pal), 5, 0.85);
        const cx = gx, cy = D * 0.45, rx = iw * 0.32, ry = id * 0.3;
        const mp = st.paths === "mown" ? "#c6da9e" : PATH[st.paths];
        s += `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="none" stroke="${mp}" stroke-width="${Math.min(0.9, W * 0.08)}"/>`;
        s += `<path d="M${gx} ${D - m} V${cy + ry}" stroke="${mp}" stroke-width="${Math.min(0.9, W * 0.08)}"/>`;
        s += tree(W * 0.22, D * 0.22, Math.min(W, D) * 0.12, "#4f6f45") + tree(W * 0.8, D * 0.7, Math.min(W, D) * 0.1, "#5e7a55");
        s += bed(r, st, m + 0.3, D - m - 1.3, Math.min(2, iw * 0.3), 1, pal, 7);
        break;
      }
      case "greenhouse": {
        const bw = Math.min(1.2, iw * 0.22), pw = Math.min(1, W * 0.12);
        s += `<rect x="${gx - pw / 2}" y="${m}" width="${pw}" height="${D - m}" fill="${pf}"/>`;
        const y0 = m + Math.min(5.5, id * 0.4);
        s += bed(r, st, m + 0.3, y0, bw, D - m - 0.5 - y0, pal, 6, 0.4) + bed(r, st, W - m - 0.3 - bw, y0, bw, D - m - 0.5 - y0, pal, 6, 0.4);
        if (iw > 6) s += bed(r, st, m + 0.6 + bw, y0 + 0.2, Math.max(0.6, gx - pw / 2 - (m + 0.9 + bw)), 1, pal, 6, 0.4) + bed(r, st, gx + pw / 2 + 0.3, y0 + 0.2, Math.max(0.6, W - m - 0.6 - bw - (gx + pw / 2 + 0.3)), 1, pal, 6, 0.4);
        break;
      }
      default: { // cottage
        const bw = Math.max(0.7, Math.min(1.8, W * 0.16));
        s += bed(r, st, m + 0.1, m + 0.1, bw, id - 0.2, pal, 9) + bed(r, st, W - m - 0.1 - bw, m + 0.1, bw, id - 0.2, pal, 9);
        s += bed(r, st, m + 0.2 + bw, m + 0.1, iw - 2 * bw - 0.4, Math.min(bw, id * 0.15), pal, 9);
        const cy = D * 0.42, cr = Math.min(W, D) * 0.14, pw = Math.min(0.9, W * 0.12);
        s += `<path d="M${gx} ${D} C ${gx - W * 0.18} ${D * 0.78}, ${gx + W * 0.16} ${D * 0.62}, ${gx} ${cy + cr}" stroke="${pf}" stroke-width="${pw}" fill="none"/>`;
        s += `<circle cx="${gx}" cy="${cy}" r="${cr}" fill="${pf}"/>` + `<circle cx="${gx}" cy="${cy}" r="${cr * 0.45}" fill="${SOIL}"/>` + plants(r, gx - cr * 0.35, cy - cr * 0.35, cr * 0.7, cr * 0.7, pal, 14, 0.8);
        break;
      }
    }
    return { s, occupied };
  }

  /* ---------------- add-ons (simple packer) ---------------- */
  function place(item, W, D, occ, prefer) {
    const m = 0.5, step = 0.5;
    const ys = []; for (let y = m; y + item.h <= D - m + 1e-6; y += step) ys.push(y);
    const xs = []; for (let x = m; x + item.w <= W - m + 1e-6; x += step) xs.push(x);
    if (prefer === "bottom") ys.reverse();
    if (prefer === "right") xs.reverse();
    if (prefer === "center") xs.sort((a, b) => Math.abs(a + item.w / 2 - W / 2) - Math.abs(b + item.w / 2 - W / 2));
    for (const y of ys) for (const x of xs) {
      const r = { x, y, w: item.w, h: item.h };
      if (!occ.some((o) => r.x < o.x + o.w + 0.2 && r.x + r.w + 0.2 > o.x && r.y < o.y + o.h + 0.2 && r.y + r.h + 0.2 > o.y)) { occ.push(r); return r; }
    }
    return null;
  }

  function addonsSvg(st, W, D, uid, pal, occ) {
    let s = "", water = "";
    const has = (id) => (st.addons || []).includes(id);
    const gh = (st.addons || []).map((id) => by(C.addons, id)).find((a) => a && a.group === "greenhouse");
    const pad = (r, fill) => `<rect x="${r.x - 0.2}" y="${r.y - 0.2}" width="${r.w + 0.4}" height="${r.h + 0.4}" rx=".25" fill="${fill}"/>`;
    const items = [];
    if (has("cabin")) items.push({ id: "cabin", w: 3, h: 3, prefer: "top" });
    if (gh) items.push({ id: "gh", w: gh.w, h: gh.d, prefer: st.layout === "greenhouse" ? "center" : "right" });
    else if (st.layout === "greenhouse") items.push({ id: "ghslot", w: 2.5, h: 4, prefer: "center" });
    if (has("pergola")) items.push({ id: "pergola", w: 3, h: 2.5, prefer: "top" });
    if (has("firepit")) items.push({ id: "firepit", w: 2.4, h: 2.4, prefer: "bottom" });
    if (has("hammock")) items.push({ id: "hammock", w: 1.2, h: 3.4, prefer: "right" });
    if (has("rainbarrel")) items.push({ id: "rainbarrel", w: 0.8, h: 0.8, prefer: "top" });
    const stream = (st.addons || []).map((id) => by(C.addons, id)).find((a) => a && a.group === "stream");
    if (stream) items.push({ id: "stream", w: stream.w, h: stream.d, prefer: "right", drop: stream.drop });
    const missing = [];
    for (const it of items) {
      const r = place(it, W, D, occ, it.prefer);
      if (!r) { missing.push(it.id); continue; }
      const cx = r.x + r.w / 2, cy = r.y + r.h / 2;
      switch (it.id) {
        case "cabin":
          s += pad(r, "#d9cfbd") + `<g filter="url(#sh${uid})"><rect x="${r.x}" y="${r.y}" width="3" height="3" fill="#7a5a3e"/><path d="M${r.x} ${r.y} L${cx} ${cy} L${r.x + 3} ${r.y} Z" fill="#8c6a4b"/><path d="M${r.x} ${r.y + 3} L${cx} ${cy} L${r.x + 3} ${r.y + 3} Z" fill="#6a4c33"/><path d="M${r.x} ${r.y}L${r.x + 3} ${r.y + 3}M${r.x + 3} ${r.y}L${r.x} ${r.y + 3}" stroke="#4e3826" stroke-width=".06"/></g><rect x="${r.x + 0.3}" y="${r.y + 3}" width="2.4" height=".6" fill="#b98c5f"/>`;
          break;
        case "gh": case "ghslot": {
          const slot = it.id === "ghslot";
          s += slot ? `<rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="none" stroke="#5d6e4c" stroke-width=".08" stroke-dasharray=".3 .2"/><text x="${cx}" y="${cy}" font-size=".38" text-anchor="middle" fill="#5d6e4c" font-family="Inter,sans-serif">+ greenhouse</text>`
            : pad(r, PATH.stone) + `<g filter="url(#sh${uid})"><rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="#e3efe9" stroke="#f7faf9" stroke-width=".1"/><path d="M${cx} ${r.y}V${r.y + r.h}" stroke="#fff" stroke-width=".12"/>${Array.from({ length: Math.floor(r.h) }, (_, i) => `<path d="M${r.x} ${r.y + i + 1}H${r.x + r.w}" stroke="#fff" stroke-width=".05"/>`).join("")}</g>` + plants(rng(7), r.x + 0.1, r.y + 0.3, r.w * 0.35, r.h - 0.6, ["#e4572e", "#f3a712"], 5, 0.4) + plants(rng(9), cx + 0.2, r.y + 0.3, r.w * 0.35, r.h - 0.6, ["#e4572e", "#f3a712"], 5, 0.4);
          break;
        }
        case "pergola":
          s += pad(r, PATH[st.paths] || PATH.gravel) + `<rect x="${r.x + 0.8}" y="${r.y + 0.6}" width="1.4" height=".8" rx=".1" fill="#f5f0e6" stroke="#b98c5f" stroke-width=".05"/>` + Array.from({ length: 7 }, (_, i) => `<rect x="${r.x}" y="${r.y + i * (r.h - 0.12) / 6}" width="${r.w}" height=".12" fill="#8a6644" opacity=".85"/>`).join("") + `<path d="M${r.x} ${r.y}V${r.y + r.h}M${r.x + r.w} ${r.y}V${r.y + r.h}" stroke="#6a4c33" stroke-width=".18"/>` + plants(rng(3), r.x, r.y, r.w, 0.5, pal, 10, 0.6);
          break;
        case "firepit":
          s += `<circle cx="${cx}" cy="${cy}" r="1.2" fill="${PATH.gravel}"/><circle cx="${cx}" cy="${cy}" r=".45" fill="#5b5550" stroke="#3a3632" stroke-width=".1"/><circle cx="${cx}" cy="${cy}" r=".25" fill="#e4572e"/><circle cx="${cx}" cy="${cy}" r=".12" fill="#f3c77a"/>` + [0, 1, 2, 3].map((k) => { const a = k * Math.PI / 2 + 0.6; return `<rect x="${cx + Math.cos(a) * 0.95 - 0.25}" y="${cy + Math.sin(a) * 0.95 - 0.12}" width=".5" height=".25" rx=".05" fill="#b98c5f" transform="rotate(${(a * 180 / Math.PI + 90).toFixed(0)} ${cx + Math.cos(a) * 0.95} ${cy + Math.sin(a) * 0.95})"/>`; }).join("");
          break;
        case "hammock":
          s += `<rect x="${r.x - 0.3}" y="${r.y}" width="${r.w + 0.6}" height="${r.h}" rx=".5" fill="url(#g${uid})"/>` + tree(cx, r.y + 0.35, 0.45, "#4f6f45") + tree(cx, r.y + r.h - 0.35, 0.45, "#5e7a55") + `<path d="M${cx} ${r.y + 0.6} Q ${cx + 0.5} ${cy} ${cx} ${r.y + r.h - 0.6}" stroke="#f5f0e6" stroke-width=".32" fill="none"/><path d="M${cx} ${r.y + 0.6} Q ${cx + 0.5} ${cy} ${cx} ${r.y + r.h - 0.6}" stroke="${pal[2] || "#b8955a"}" stroke-width=".1" fill="none" stroke-dasharray=".15 .1"/>`;
          break;
        case "stream": {
          // lined recirculating stream: rock waterfall at the top, meandering channel, pump basin at the bottom
          const w = r.w, h = r.h, x0 = r.x, y0 = r.y;
          const pts = [[x0 + w * 0.65, y0 + 0.55], [x0 + w * 0.35, y0 + h * 0.3], [x0 + w * 0.7, y0 + h * 0.52], [x0 + w * 0.4, y0 + h * 0.72], [x0 + w * 0.5, y0 + h - 0.6]];
          const d = "M" + pts.map((p) => p.map((v) => v.toFixed(2)).join(" ")).join(" L");
          s += `<path d="${d}" stroke="#8f8a82" stroke-width="${(0.75).toFixed(2)}" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" stroke="#6fa8c9" stroke-width=".42" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" stroke="#bfe0ef" stroke-width=".12" fill="none" stroke-dasharray=".3 .4" stroke-linecap="round"/>`;
          s += `<ellipse cx="${x0 + w * 0.5}" cy="${y0 + h - 0.45}" rx="${Math.min(0.75, w * 0.35)}" ry=".45" fill="#5b93b5" stroke="#8f8a82" stroke-width=".14"/>`;
          const rr = rng(11); for (let k = 0; k < 7; k++) s += `<ellipse cx="${(x0 + w * 0.65 + (rr() - 0.5) * 0.9).toFixed(2)}" cy="${(y0 + 0.4 + (rr() - 0.5) * 0.5).toFixed(2)}" rx="${(0.18 + rr() * 0.16).toFixed(2)}" ry="${(0.14 + rr() * 0.1).toFixed(2)}" fill="${["#8f8a82", "#a29d94", "#7d7870"][k % 3]}" filter="url(#sh${uid})"/>`;
          break;
        }
        case "rainbarrel":
          s += `<circle cx="${cx}" cy="${cy}" r=".35" fill="#4a7fa8" stroke="#2f5877" stroke-width=".06"/><circle cx="${cx}" cy="${cy}" r=".2" fill="#7fb0d4"/>`;
          break;
      }
    }
    if (has("watering")) {
      water = `<g stroke="#3f8fd0" stroke-width=".06" stroke-dasharray=".12 .18" fill="none" opacity=".95">`;
      for (let y = 1.2; y < D - 0.8; y += 1.7) water += `<path d="M.6 ${y.toFixed(2)}H${(W - 0.6).toFixed(2)}"/>`;
      water += `</g><rect x=".45" y="${D - 0.95}" width=".5" height=".5" rx=".08" fill="#17241c"/><circle cx=".7" cy="${D - 0.7}" r=".1" fill="#3f8fd0"/>`;
    }
    return { s, water, missing };
  }

  function render(st, opts = {}) {
    const plot = C.plots.find((p) => p.m2 === st.plot) || C.plots[2];
    const W = plot.w, D = plot.d, uid = opts.uid || "p";
    const pal = (by(C.palettes, st.palette) || C.palettes[0]).colors;
    const r = rng(plot.m2 * 31 + st.layout.length * 7 + (st.palette || "").length);
    const pad = opts.mini ? 0.4 : Math.max(1.2, Math.max(W, D) * 0.08);
    const vb = `${-pad} ${-pad} ${W + 2 * pad} ${D + 2 * pad + (opts.mini ? 0 : pad * 0.6)}`;
    const L = layoutSvg(st, W, D, uid, pal, r);
    const A = addonsSvg(st, W, D, uid, pal, L.occupied);
    const fs = Math.max(0.32, Math.max(W, D) * 0.035);
    let s = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">${defs(uid, st)}`;
    s += `<rect x="${-pad}" y="${-pad}" width="${W + 2 * pad}" height="${D + 3 * pad}" fill="${opts.mini ? "transparent" : "#f3eee4"}"/>`;
    s += `<rect x="0" y="0" width="${W}" height="${D}" fill="url(#g${uid})"/>`;
    s += L.s + A.s + A.water;
    // hedge with gate gap
    const hw = 0.35, gx = W / 2;
    s += `<path d="M${gx - 0.6} ${D} H0 V0 H${W} V${D} H${gx + 0.6}" fill="none" stroke="#3f5a3f" stroke-width="${hw}" stroke-linejoin="round"/>`;
    if (!opts.mini) {
      s += `<text x="${gx}" y="${D + fs * 1.6}" font-size="${fs}" text-anchor="middle" fill="#6b7464" font-family="Inter,sans-serif">▲ ${opts.gateLabel || "gate"}</text>`;
      s += `<text x="${W / 2}" y="${-pad * 0.35}" font-size="${fs}" text-anchor="middle" fill="#6b7464" font-family="Inter,sans-serif">${W} m</text>`;
      s += `<text x="${-pad * 0.35}" y="${D / 2}" font-size="${fs}" text-anchor="middle" fill="#6b7464" font-family="Inter,sans-serif" transform="rotate(-90 ${-pad * 0.35} ${D / 2})">${D} m</text>`;
      const sb = W >= 10 ? 5 : 1; // scale bar
      s += `<g transform="translate(0 ${D + fs * 2.6})"><rect width="${sb}" height="${fs * 0.3}" fill="#17241c"/><text x="${sb + 0.3}" y="${fs * 0.35}" font-size="${fs * 0.85}" fill="#6b7464" font-family="Inter,sans-serif">${sb} m</text></g>`;
    }
    s += `</svg>`;
    return { svg: s, missing: A.missing };
  }

  window.UnelmPlan = { render };
})();

