/* Vision board page: mood-board grid of sample corners, stream & waterfall kits, learning path + badges. EN/ET. */
(function () {
  const C = window.UNELM_CONFIG, P = window.UnelmPricing, V = window.UNELM_VISION, LN = window.UnelmLearn;
  const qs = new URLSearchParams(location.search);
  let lang = qs.get("lang") || localStorage.getItem("unelm-lang") || "en"; if (!["en", "et"].includes(lang)) lang = "en";
  let KIT = null;
  const by = (a, id) => a.find((x) => x.id === id);
  const T = {
    en: { brandTag: "Garden Retreat", navBoard: "Corners", navStream: "Stream & waterfall", navLearn: "Learning path", navHome: "Home", navCta: "Open the designer",
      foot: "All images on this page are illustrative concepts, rendered by code – not photos of a finished garden.",
      eyebrow: "Vision board", h1: "Garden corners to spark your <em class=\"s\">imagination</em>",
      lead: "Six sample corners for our Estonian countryside plots – wet, fertile loam, so everything grows in raised beds. Each one is designed for you to build yourself, step by step, with a guide on call.",
      chips: ["🧰 You build it, we guide you", "🌱 Learn by doing", "📦 Materials ordered after booking"],
      illus: "Illustrative concept", open: "Open the corner", steps: "{n} step cards · ≈ {h}", plan: "2D plan", view: "3D view", closeUp: "Close-up",
      add: "Add-ons for this corner", start: "Start with this corner in the designer", close: "Close", from: "from", perPerson: "per person",
      streamEyebrow: "New add-on", streamH: "Stream & waterfall – oja ja kosk", streamP: "A lined, recirculating stream with a rock waterfall, built by you in a weekend with our step cards. Materials are bought only after you book – nothing sits in a warehouse.",
      incl: "What's in the kit", kitPrice: "Kit price", builder: "Optional: hire a local builder", solar: "Solar pump instead of mains: {x} (gentle trickle on sunny days – small kit only).", epdm: "EPDM rubber liner upgrade (20+ years): +{x}", matNote: "Materials ordered after booking", flow: "Pump",
      learnEyebrow: "How you learn", learnH: "You build it, <em class=\"s\">we guide you</em>",
      learnP: "Grown-ups learn best by doing something useful straight away – on their own terms. So every corner comes as a learning path of short step cards you can tackle in any order.",
      principles: [["Learn by doing", "Each card is one real job in your garden – a bed, a path, a stream – done in an afternoon."], ["Your choice, your pace", "Pick the corner, the order and the pace. Skip what you already know."], ["Useful today", "Every step ends with something you can use tonight: a planted bed, a working pump."], ["Help when you want it", "Ask your guide, join a group workshop or book a 1:1 session at your plot."]],
      wsH: "Optional on-site workshops", ws: [["Group workshop", "2 h on site with other guests – e.g. raised beds, drip watering, stream & waterfall.", "ws_group"], ["1:1 guidance session", "A guide at your plot for your trickiest step. One session is included with the self-build service.", "ws_1to1"]],
      assumption: "ASSUMPTION · example price", badgesH: "Badges for finished steps", badgesP: "Tick every item on a step card to finish it and earn its badge. Progress is saved only in this browser (prototype).",
      builderLink: "Prefer not to build? A local builder can do it for you (optional).", tryIt: "Try it: open a corner and tick a step." },
    et: { brandTag: "Aiapuhkus", navBoard: "Aianurgad", navStream: "Oja ja kosk", navLearn: "Õpiteekond", navHome: "Avaleht", navCta: "Ava kujundaja",
      foot: "Kõik selle lehe pildid on illustratiivsed näidised, mis on loodud koodiga – mitte fotod valmis aiast.",
      eyebrow: "Inspiratsioon", h1: "Aianurgad, mis <em class=\"s\">inspireerivad</em>",
      lead: "Kuus näidisnurka meie maakrundidele – niiske ja viljakas liivsavi, seega kasvab kõik kõrgpeenardes. Iga nurk on mõeldud selleks, et ehitad selle ise, samm-sammult, juhendaja toel.",
      chips: ["🧰 Sina ehitad, meie juhendame", "🌱 Õpi tehes", "📦 Materjalid tellitakse pärast broneeringut"],
      illus: "Illustratiivne näidis", open: "Ava nurk", steps: "{n} sammukaarti · ≈ {h}", plan: "2D-plaan", view: "3D-vaade", closeUp: "Lähivaade",
      add: "Lisad sellele nurgale", start: "Alusta sellest nurgast kujundajas", close: "Sulge", from: "alates", perPerson: "inimese kohta",
      streamEyebrow: "Uus lisa", streamH: "Oja ja kosk", streamP: "Kilega vooderdatud ringlev oja kivikosega – ehitad selle nädalavahetusega meie sammukaartide abil. Materjalid ostame alles pärast broneeringut – laos ei seisa midagi.",
      incl: "Komplekti sisu", kitPrice: "Komplekti hind", builder: "Valikuline: palka kohalik ehitaja", solar: "Päikesepump võrgupumba asemel: {x} (õrn nire päikesega – ainult väike komplekt).", epdm: "EPDM kummikile (20+ aastat): +{x}", matNote: "Materjalid tellitakse pärast broneeringut", flow: "Pump",
      learnEyebrow: "Kuidas õpid", learnH: "Sina ehitad, <em class=\"s\">meie juhendame</em>",
      learnP: "Täiskasvanud õpivad kõige paremini, kui teevad kohe midagi kasulikku – omal moel. Seepärast on iga nurga juures õpiteekond lühikestest sammukaartidest, mida võid teha mis tahes järjekorras.",
      principles: [["Õpi tehes", "Iga kaart on üks päris töö sinu aias – peenar, rada, oja – tehtud ühe pärastlõunaga."], ["Sinu valik, sinu tempo", "Vali nurk, järjekord ja tempo. Jäta vahele, mida juba oskad."], ["Kasulik kohe", "Iga samm lõpeb millegagi, mida saad kohe kasutada: istutatud peenar, töötav pump."], ["Abi siis, kui soovid", "Küsi juhendajalt, tule grupitöötuppa või broneeri 1:1 juhendamine oma krundil."]],
      wsH: "Valikulised töötoad kohapeal", ws: [["Grupitöötuba", "2 h kohapeal koos teiste külalistega – nt kõrgpeenrad, tilkkastmine, oja ja kosk.", "ws_group"], ["1:1 juhendamine", "Juhendaja sinu krundil kõige keerulisema sammu juures. Üks kord sisaldub ise-ehitamise teenuses.", "ws_1to1"]],
      assumption: "EELDUS · näidishind", badgesH: "Märgid tehtud sammude eest", badgesP: "Märgi sammukaardil kõik punktid, et samm lõpetada ja märk teenida. Edenemine salvestub ainult selles brauseris (prototüüp).",
      builderLink: "Ei soovi ise ehitada? Kohalik ehitaja saab seda teha (valikuline).", tryIt: "Proovi: ava nurk ja märgi samm tehtuks." }
  };
  const t = (k) => T[lang][k] ?? T.en[k] ?? k;
  const f = (s, o) => s.replace(/\{(\w+)\}/g, (_, k) => o[k]);
  const img = (src, alt, cls = "") => `<figure class="vimgbox ${cls}"><img src="${src}" alt="${alt}" loading="lazy"><figcaption class="illus">${t("illus")}</figcaption></figure>`;

  function tiles() {
    // mood board: per concept a big 3D tile, a plan tile and a close-up tile, interleaved for rhythm
    const out = [];
    V.concepts.forEach((c, i) => {
      const p = LN.progress(c), base = `../assets/vision/${c.id}`;
      out.push(`<button type="button" class="tile t-hero" data-id="${c.id}">${img(base + "-3d-1.jpg", c.name[lang] + " – " + t("illus"))}<div class="tcap"><span class="tier">${c.plot} m²</span><b>${c.name[lang]}</b><span>${c.tagline[lang]}</span><small>${f(t("steps"), { n: c.lessons.length, h: LN.dur(p.minutes, lang) })}${p.done ? ` · ✓ ${p.done}/${p.total}` : ""}</small></div></button>`);
      out.push(`<button type="button" class="tile t-plan" data-id="${c.id}" data-tab="plan">${img(base + "-plan.png", c.name[lang] + " – " + t("plan"))}<div class="tcap small"><b>${t("plan")}</b><span>${c.name[lang]}</span></div></button>`);
      out.push(`<button type="button" class="tile t-close" data-id="${c.id}" data-tab="close">${img(base + "-3d-2.jpg", c.name[lang] + " – " + t("closeUp"))}<div class="tcap small"><b>${t("closeUp")}</b><span>${c.features.slice(0, 2).map((x) => x[lang]).join(" · ")}</span></div></button>`);
    });
    return out.join("");
  }
  function kitCard(id, size) {
    const a = by(C.addons, id), k = KIT && KIT.kits[size];
    const lines = k ? k.lines.filter((l) => l.id !== "delivery").map((l) => `<li>${l.name[lang]}</li>`).join("") : "";
    return `<article class="kit"><div class="kit-top"><h3>${t("addons_" + id) || (k ? k.name[lang] : id)}</h3><p>${k ? k.spec[lang] : ""}</p></div>
      <div class="kit-price"><small>${t("kitPrice")}</small><b>${P.fmt(a.price)}</b><span class="note">📦 ${t("matNote")}</span></div>
      <details><summary>${t("incl")}</summary><ul>${lines}</ul></details>
      <p class="kit-opt">🔧 ${t("builder")}: <b>+${P.fmt(a.labour)}</b></p>
      ${size === "small" && KIT ? `<p class="kit-opt">☀️ ${f(t("solar"), { x: (KIT.options.solar.deltaVsMains.small < 0 ? "−" : "+") + P.fmt(Math.abs(KIT.options.solar.deltaVsMains.small)) })}</p>` : ""}
      ${KIT ? `<p class="kit-opt">🛡️ ${f(t("epdm"), { x: P.fmt(KIT.options.epdm[size].extraPrice) })}</p>` : ""}</article>`;
  }
  T.en.addons_stream_s = "Small stream & waterfall"; T.et.addons_stream_s = "Väike oja ja kosk"; T.en.addons_stream_m = "Medium stream & waterfall"; T.et.addons_stream_m = "Keskmine oja ja kosk";

  function render() {
    document.documentElement.lang = lang;
    document.querySelectorAll("[data-t]").forEach((el) => (el.textContent = t(el.dataset.t)));
    document.querySelectorAll(".lang button").forEach((b) => b.setAttribute("aria-pressed", b.dataset.lang === lang));
    const ws = (id) => by(C.addons, id);
    document.getElementById("main").innerHTML = `
      <section class="vhero-sec"><div class="wrap"><span class="eyebrow">${t("eyebrow")}</span><h1>${t("h1")}</h1><p class="lead">${t("lead")}</p>
        <div class="vchips">${t("chips").map((c) => `<span>${c}</span>`).join("")}</div></div></section>
      <section id="board" class="board-sec"><div class="wrap"><div class="board">${tiles()}</div><p class="vnote">${t("tryIt")} · ${t("builderLink")}</p></div></section>
      <section id="stream" class="stream-sec"><div class="wrap"><div class="stream-head"><div><span class="eyebrow">${t("streamEyebrow")}</span><h2>${t("streamH")}</h2><p>${t("streamP")}</p></div>
        ${img("../assets/vision/stream100-3d-2.jpg", t("streamH") + " – " + t("illus"), "stream-img")}</div>
        <div class="kits">${kitCard("stream_s", "small")}${kitCard("stream_m", "medium")}</div>
        ${C.pricesArePlaceholders ? `<p class="vnote">${lang === "et" ? "Komplekti hinnad põhinevad Eesti poodide hindadel (27.09.2026); ehitaja tasu ja transport on eeldused." : "Kit prices are based on Estonian shop prices (27 Sep 2026); the builder fee and stone delivery are assumptions."}</p>` : ""}</div></section>
      <section id="learn" class="learn-sec"><div class="wrap"><span class="eyebrow">${t("learnEyebrow")}</span><h2>${t("learnH")}</h2><p class="lead">${t("learnP")}</p>
        <div class="princ">${t("principles").map(([h, p], i) => `<div><span>${["🛠️", "🧭", "🌿", "🤝"][i]}</span><b>${h}</b><p>${p}</p></div>`).join("")}</div>
        <h3 class="sub">${t("wsH")}</h3><div class="wsgrid">${t("ws").map(([h, p, id]) => `<div class="wscard"><b>${h}</b><p>${p}</p><div class="wsprice">${P.fmt(ws(id).price)}${id === "ws_group" ? ` <small>${t("perPerson")}</small>` : ""} <span class="tag-example">${t("assumption")}</span></div></div>`).join("")}</div>
        <h3 class="sub">${t("badgesH")}</h3><p class="vnote">${t("badgesP")}</p>${LN.badgesHTML(lang)}</div></section>`;
    document.querySelectorAll(".tile").forEach((b) => (b.onclick = () => openModal(b.dataset.id, b.dataset.tab || "hero")));
  }

  function openModal(id, tab = "hero") {
    const c = V.concepts.find((x) => x.id === id), base = `../assets/vision/${c.id}`;
    const srcs = { hero: base + "-3d-1.jpg", close: base + "-3d-2.jpg", plan: base + "-plan.png" };
    const addons = (c.addable || []).map((aid) => by(C.addons, aid)).filter(Boolean).map((a) => {
      const nm = { en: { gh_s: "Greenhouse S", gh_l: "Greenhouse L", watering: "Automatic watering", rainbarrel: "Rain barrel", cabin: "Garden cabin (local builder)", firepit: "Fire pit", hammock: "Hammock", pergola: "Pergola & seating", stream_s: "Stream & waterfall S", stream_m: "Stream & waterfall M" }, et: { gh_s: "Kasvuhoone S", gh_l: "Kasvuhoone L", watering: "Automaatne kastmine", rainbarrel: "Vihmaveetünn", cabin: "Aiamaja (kohalik ehitaja)", firepit: "Lõkkease", hammock: "Võrkkiik", pergola: "Pergola ja istumisnurk", stream_s: "Oja ja kosk S", stream_m: "Oja ja kosk M" } }[lang][a.id] || a.id;
      return `<li><span>${nm}${a.group === "stream" ? ` <small>📦 ${t("matNote")}</small>` : ""}</span><b>${a.kit ? "" : t("from") + " "}${P.fmt(a.kit ? a.price : a.price * by(C.services, "diy").materialFactor)}</b></li>`; }).join("");
    const box = document.getElementById("mbox");
    box.innerHTML = `<button class="mclose" data-close aria-label="${t("close")}">✕</button>
      <div class="mgrid"><div class="mgal"><div class="mmain">${img(srcs[tab], c.name[lang] + " – " + t("illus"), tab === "plan" ? "isplan" : "")}</div>
        <div class="mthumbs">${[["hero", t("view")], ["close", t("closeUp")], ["plan", t("plan")]].map(([k, l]) => `<button type="button" data-tab="${k}" aria-pressed="${k === tab}"><img src="${srcs[k]}" alt=""><span>${l}</span></button>`).join("")}</div></div>
      <div class="minfo"><span class="eyebrow">${c.plot} m² · ${c.w} × ${c.d} m</span><h2 id="mTitle">${c.name[lang]}</h2><p class="youbuild">🧰 ${V.youBuild[lang]}</p><p>${c.text[lang]}</p>
        <ul class="mfeat">${c.features.map((x) => `<li>${x[lang]}</li>`).join("")}</ul>
        <h3 class="sub">${t("add")}</h3><ul class="madd">${addons}</ul>
        <div id="mlearn">${LN.cardsHTML(c, lang)}</div>
        <a class="btn btn-gold" href="../app/?concept=${c.id}&lang=${lang}">${t("start")} →</a></div></div>`;
    const m = document.getElementById("modal"); m.hidden = false; document.body.style.overflow = "hidden";
    box.querySelectorAll("[data-close]").forEach((b) => (b.onclick = closeModal));
    box.querySelectorAll(".mthumbs button").forEach((b) => (b.onclick = () => { const y = box.scrollTop; openModal(id, b.dataset.tab); box.scrollTop = y; }));
    const bindL = () => LN.bind(document.getElementById("mlearn"), (lid) => { document.getElementById("mlearn").innerHTML = LN.cardsHTML(c, lang, { open: c.lessons.indexOf(lid) }); bindL(); });
    bindL();
  }
  function closeModal() { document.getElementById("modal").hidden = true; document.body.style.overflow = ""; render(); }
  document.querySelector(".vmodal-bg").onclick = closeModal;
  document.addEventListener("keydown", (e) => e.key === "Escape" && !document.getElementById("modal").hidden && closeModal());
  document.querySelectorAll(".lang button").forEach((b) => (b.onclick = () => { lang = b.dataset.lang; try { localStorage.setItem("unelm-lang", lang); } catch (e) {} render(); }));
  render();
  fetch("../assets/js/stream-kit.json").then((r) => r.json()).then((j) => { KIT = j; render(); if (qs.get("open")) openModal(qs.get("open"), qs.get("tab") || "hero"); }).catch(() => { if (qs.get("open")) openModal(qs.get("open")); });
})();
